use std::fs

fn best(prios: Vec<int>) -> int {
    let mut b = 0
    let mut i = 1
    while i < prios.len() as int {
        if prios[i] > prios[b] {
            b = i
        }
        i += 1
    }
    b
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut names: Vec<string> = []
    let mut prios: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|p| p.to_string()).collect()
        let n = parts.len() as int
        if n == 3 && parts[0] == "add" {
            match parts[2].parse::<int>() {
                Ok(p) => {
                    names.push(parts[1])
                    prios.push(p)
                }
                Err(_) => println("error")
            }
        } else if n == 1 && parts[0] == "pop" {
            if names.len() == 0 {
                println("empty")
            } else {
                let b = best(prios)
                println(names[b])
                names.remove(b)
                prios.remove(b)
            }
        } else if n == 1 && parts[0] == "peek" {
            if names.len() == 0 {
                println("empty")
            } else {
                println(names[best(prios)])
            }
        } else if n == 1 && parts[0] == "size" {
            println("${names.len()}")
        } else {
            println("error")
        }
    }
    println("left:")
    while names.len() > 0 {
        let b = best(prios)
        println("${names[b]} ${prios[b]}")
        names.remove(b)
        prios.remove(b)
    }
}

